// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.localimport timber.log.Timberimport java.io.Fileimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — LoRA Adapter Manager (Strategy §4.8). * * Manages LoRA (Low-Rank Adaptation) adapter loading/unloading for * [LlamaCppProvider]. LoRA adapters are ~20MB files that fine-tune the * base model for specific tasks without retraining the full model. * * ## Use Cases (Strategy §4.8) * *   - **Hinglish adapter** — improves Hindi-English code-switching *   - **Coding adapter** — better code generation *   - **Medical adapter** — medical terminology *   - **Persona-specific adapters** — Atlas speaks differently than Nova * * ## Hot-Swapping * * The JNI bridge supports loading/unloading adapters without reloading the * base model. Swap takes ~500ms vs 5 seconds for a full model reload. * Multiple adapters can be loaded simultaneously (up to 4 by default). * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§4.8 LoRA Adapter Support</a> */@Singletonclass LoraAdapterManager @Inject constructor(    private val kvCacheManager: KvCacheManager,) {    /** Maximum number of simultaneously loaded adapters. */    private val maxAdapters: Int = 4    /** Currently loaded adapters: handle → info. */    private val loadedAdapters = java.util.concurrent.ConcurrentHashMap<Long, LoraAdapterInfo>()    /** Directory where LoRA adapter files are stored. */    private val loraDir: String = "loras"    /**     * Load a LoRA adapter onto an existing model context.     *     * @param contextPtr native llama.cpp context pointer     * @param adapterId unique adapter ID (e.g., "hinglish", "coding")     * @param scale scaling factor (1.0 = full strength, 0.5 = half)     * @return adapter handle (>0 on success, 0 on failure)     */    suspend fun loadAdapter(        contextPtr: Long,        adapterId: String,        scale: Float = 1.0f,    ): Long {        if (loadedAdapters.size >= maxAdapters) {            Timber.w("Max LoRA adapters (%d) already loaded — unload one first", maxAdapters)            return 0L        }        val loraPath = getAdapterPath(adapterId)        val loraFile = File(loraPath)        if (!loraFile.exists()) {            Timber.w("LoRA adapter file not found: %s", loraPath)            return 0L        }        return try {            val handle = LlamaCppJni.nativeLoadLoraAdapter(contextPtr, loraPath, scale)            if (handle > 0) {                loadedAdapters[handle] = LoraAdapterInfo(                    handle = handle,                    adapterId = adapterId,                    path = loraPath,                    scale = scale,                    loadedAtMs = System.currentTimeMillis(),                )                // Clear KV cache — the adapter changes the model's behavior.                kvCacheManager.clearCache()                Timber.i("LoRA adapter loaded: %s (handle=%d, scale=%.2f)", adapterId, handle, scale)                handle            } else {                Timber.w("Failed to load LoRA adapter: %s (native returned 0)", adapterId)                0L            }        } catch (e: UnsatisfiedLinkError) {            Timber.w(e, "Native library not loaded — LoRA adapter support unavailable")            0L        } catch (e: Exception) {            Timber.e(e, "Failed to load LoRA adapter: %s", adapterId)            0L        }    }    /**     * Unload a LoRA adapter from a model context.     *     * @param contextPtr native llama.cpp context pointer     * @param adapterId the adapter ID to unload     * @return true on success     */    suspend fun unloadAdapter(contextPtr: Long, adapterId: String): Boolean {        val info = loadedAdapters.values.find { it.adapterId == adapterId }            ?: return false        return try {            val success = LlamaCppJni.nativeUnloadLoraAdapter(contextPtr, info.handle)            if (success) {                loadedAdapters.remove(info.handle)                kvCacheManager.clearCache()                Timber.i("LoRA adapter unloaded: %s", adapterId)            }            success        } catch (e: UnsatisfiedLinkError) {            false        } catch (e: Exception) {            Timber.e(e, "Failed to unload LoRA adapter: %s", adapterId)            false        }    }    /**     * Unload all LoRA adapters.     *     * @param contextPtr native llama.cpp context pointer     */    suspend fun unloadAll(contextPtr: Long) {        val adapters = loadedAdapters.values.toList()        for (adapter in adapters) {            try {                LlamaCppJni.nativeUnloadLoraAdapter(contextPtr, adapter.handle)            } catch (e: Throwable) { Timber.tag("NOUS.LLM").w(e, "LoRA adapter unload failed") }        }        loadedAdapters.clear()        kvCacheManager.clearCache()        Timber.i("All LoRA adapters unloaded (%d)", adapters.size)    }    /**     * List all currently loaded adapters.     *     * @return list of adapter info     */    fun listLoadedAdapters(): List<LoraAdapterInfo> = loadedAdapters.values.toList()    /**     * List all available adapter files on disk.     *     * @param context Android context for file access     * @return list of adapter IDs (filenames without extension)     */    fun listAvailableAdapters(context: android.content.Context): List<String> {        val dir = File(context.filesDir, loraDir)        if (!dir.exists()) return emptyList()        return dir.listFiles { f -> f.extension == "gguf" }            ?.map { it.nameWithoutExtension }            ?: emptyList()    }    /**     * Get the file path for an adapter ID.     */    private fun getAdapterPath(adapterId: String): String {        return "/data/data/com.roshan.persona/files/$loraDir/$adapterId.gguf"    }    /**     * Check if any adapters are currently loaded.     */    fun hasLoadedAdapters(): Boolean = loadedAdapters.isNotEmpty()}/** * Information about a loaded LoRA adapter. * * @property handle native adapter handle (from [LlamaCppJni.nativeLoadLoraAdapter]) * @property adapterId unique adapter ID (e.g., "hinglish") * @property path file path to the .gguf adapter file * @property scale scaling factor (1.0 = full strength) * @property loadedAtMs timestamp when the adapter was loaded */data class LoraAdapterInfo(    val handle: Long,    val adapterId: String,    val path: String,    val scale: Float,    val loadedAtMs: Long,)